mapper.select:
SELECT tl.*, u.user_name AS userName, s.NAME AS supplierName FROM t_purchase_list tl LEFT JOIN t_user u ON tl.user_id = u.id LEFT JOIN t_supplier s ON tl.supplier_id = s.id
AND tl.purchase_number = #{purchaseListQuery.purchaseNumber}
AND tl.supplier_id = #{purchaseListQuery.supplierId}
AND tl.state = #{purchaseListQuery.state}
AND tl.purchase_date >= TO_DATE(#{purchaseListQuery.startDate}, 'YYYY-MM-DD')
AND tl.purchase_date <= TO_DATE(#{purchaseListQuery.endDate}, 'YYYY-MM-DD') + 1
ORDER BY tl.purchase_date DESC
